<?php

namespace App\Enums;

/**
 * Defines application permissions.
 * Generated by: php artisan permissions:generate-enum
 *
 * DO NOT EDIT MANUALLY - Re-run the command to update.
 */
enum PermissionEnum: string
{
    case COURSE_CREATE = 'courses.create';
    case COURSE_DELETE = 'courses.delete';
    case COURSE_DELETE_ANY = 'courses.delete_any';
    case COURSE_UPDATE = 'courses.update';
    case COURSE_UPDATE_ANY = 'courses.update_any';
    case COURSE_VIEW = 'courses.view';
    case COURSE_VIEW_ANY = 'courses.view_any';

    /**
     * Get all permission values as an array.
     * @return array<string>
     */
    public static function getAllValues(): array
    {
        return array_column(self::cases(), 'value');
    }

    /**
     * Get all permission names (enum case names) as an array.
     * @return array<string>
     */
    public static function getAllNames(): array
    {
        return array_column(self::cases(), 'name');
    }
}
